import{_ as t,o as a,c as o,ah as i}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Free signup and full-feature demo","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/admission/ecoles/inscription-et-demo.md","filePath":"src/en/admission/ecoles/inscription-et-demo.md"}'),n={name:"en/admission/ecoles/inscription-et-demo.md"};function r(s,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="free-signup-and-full-feature-demo" tabindex="-1">Free signup and full-feature demo <a class="header-anchor" href="#free-signup-and-full-feature-demo" aria-label="Permalink to &quot;Free signup and full-feature demo&quot;">​</a></h1><p>Discovering ERA requires no installation and no commitment: your school can create its own online space in a few minutes, for free and with no time limit, then switch to a full-feature demo to evaluate the whole solution before choosing a license.</p><h2 id="creating-your-school-s-account" tabindex="-1">Creating your school&#39;s account <a class="header-anchor" href="#creating-your-school-s-account" aria-label="Permalink to &quot;Creating your school&#39;s account&quot;">​</a></h2><p>Signup happens on Era Admission&#39;s public site: click <strong>Create my free space</strong> on its home page, then fill in a very short form:</p><ol><li>Your school&#39;s name.</li><li>Your name.</li><li>An email address.</li><li>A password.</li></ol><p>Submitting it automatically creates two things:</p><ul><li><strong>A dedicated space for your school</strong>, reachable at its own address (a subdomain built from your school&#39;s name, e.g. <code>college-sainte-marie.&lt;era-domain&gt;</code>).</li><li><strong>Your administrator account</strong>, with the email address and password you just chose — this is the account that then manages everything else (users, structure, admissions...).</li></ul><p>A confirmation page reminds you of your space&#39;s address and lets you log in right away. Keep that address — it&#39;s the one your team will use day to day.</p><h2 id="what-the-free-tier-covers" tabindex="-1">What the free tier covers <a class="header-anchor" href="#what-the-free-tier-covers" aria-label="Permalink to &quot;What the free tier covers&quot;">​</a></h2><p>The free tier isn&#39;t a limited version of all of ERA: it&#39;s a single module, built so you can get started right away —</p><ul><li>the <strong>public application form</strong>, which families can already use from day one to submit an application;</li><li>the <strong>read-only application queue</strong>, to keep track of what comes in.</li></ul><p>The rest of the application (academic life, finances, family relations, the reporting dashboard...) isn&#39;t accessible on this tier. If you want to see the application as a whole before committing, that&#39;s what the full-feature demo below is for.</p><h2 id="activating-the-full-feature-demo" tabindex="-1">Activating the full-feature demo <a class="header-anchor" href="#activating-the-full-feature-demo" aria-label="Permalink to &quot;Activating the full-feature demo&quot;">​</a></h2><p>Once logged into your space on the free tier, your administrator account sees an invitation on its dashboard to activate a full-feature demo: it temporarily unlocks every ERA module, with no commitment, so you can evaluate the solution under real conditions before choosing a license.</p><p>Activation itself — and how the demo winds down (duration, the &quot;expiring soon&quot; banner, the read-only freeze) — is covered from the administrator&#39;s point of view in <a href="/era-guide/en/guide/admin/demo-et-journal.html">Full-feature demo and activity log</a>; this guide doesn&#39;t duplicate that content.</p><p>In short, what matters before you decide:</p><ul><li>The demo runs for a fixed number of days from activation.</li><li>It can only be activated once, from the free tier — you can&#39;t restart it indefinitely on your own.</li><li>Once active, it can only be ended early by the edPage team (see <a href="/era-guide/en/admission/staff-edpage/">the internal edPage panel</a>), not from your dashboard.</li></ul><h2 id="what-happens-when-the-demo-ends" tabindex="-1">What happens when the demo ends <a class="header-anchor" href="#what-happens-when-the-demo-ends" aria-label="Permalink to &quot;What happens when the demo ends&quot;">​</a></h2><p>If no license has been purchased by the time the demo period ends, access to your space automatically switches to <strong>read-only</strong>: you can still view your data, but no longer change it. It&#39;s the same state a demo manually ended by the edPage team would reach.</p><p>This read-only state isn&#39;t final right away, but it isn&#39;t permanent either: you&#39;re given a <strong>grace period</strong> to choose a license or contact us. Past that period with no action on your part, the school — including its data — is <strong>permanently deleted</strong>, with no way to recover it.</p><p>To avoid reaching that point, see <a href="/era-guide/en/admission/ecoles/passage-licence.html">Moving to a license</a> as soon as you&#39;re ready to commit.</p>',21)])])}const p=t(n,[["render",r]]);export{m as __pageData,p as default};
